package java.util;
public class Hashtable<K,V> extends Dictionary<K,V> implements Map<K,V>,Cloneable,java.io.Serializable {private final HashMap<K,V> m;public Hashtable(){m=new HashMap<K,V>();}public Hashtable(int capacity){m=new HashMap<K,V>(capacity);}public Hashtable(int capacity,float loadFactor){m=new HashMap<K,V>(capacity,loadFactor);}public Hashtable(Map<? extends K,? extends V> t){this();putAll(t);}public synchronized int size(){return m.size();}public synchronized boolean isEmpty(){return m.isEmpty();}public synchronized Enumeration<K> keys(){return Collections.enumeration(m.keySet());}public synchronized Enumeration<V> elements(){return Collections.enumeration(m.values());}public synchronized boolean contains(Object v){return containsValue(v);}public synchronized boolean containsValue(Object v){if(v==null)throw new NullPointerException();return m.containsValue(v);}public synchronized boolean containsKey(Object k){if(k==null)throw new NullPointerException();return m.containsKey(k);}public synchronized V get(Object k){if(k==null)throw new NullPointerException();return m.get(k);}public synchronized V put(K k,V v){if(k==null||v==null)throw new NullPointerException();return m.put(k,v);}public synchronized V remove(Object k){if(k==null)throw new NullPointerException();return m.remove(k);}public synchronized void putAll(Map<? extends K,? extends V> t){for(Entry<? extends K,? extends V> e:t.entrySet())put(e.getKey(),e.getValue());}public synchronized void clear(){m.clear();}public Set<K> keySet(){return m.keySet();}public Set<Entry<K,V>> entrySet(){return m.entrySet();}public Collection<V> values(){return m.values();}public synchronized boolean equals(Object o){return o==this||m.equals(o);}public synchronized int hashCode(){return m.hashCode();}public synchronized String toString(){return m.toString();}public synchronized Object clone(){return new Hashtable<K,V>(this);}}
